export const WIDTH=3100,HEIGHT=1700;
export const SHRINES=[{id:'memory',x:720,y:600,name:'Echo of Memory',region:0},{id:'balance',x:1640,y:1130,name:'Echo of Generosity',region:1},{id:'wisdom',x:2510,y:590,name:'Echo of Wisdom',region:2}];
export const NPCS=[{x:380,y:900,name:'The Storykeeper',type:'tortoise',text:'I once tried to keep every wise idea in a gourd. Terrible storage solution. Restore the three echoes, then find the broken sky gate. Start at the glowing shrine north-east of here.'},{x:550,y:1150,name:'Sade · Weaver',type:'human',text:'The lanterns remember their order. Watch, then repeat. If you miss a note, try again. Listening is a skill, not a talent you are born with.'},{x:1240,y:900,name:'River Courier',type:'human',text:'The storm wisps steal your energy. Space sends out a shell pulse to push them back. Dash with Shift, but save a little energy for the way home.'},{x:1580,y:740,name:'Mbe · Trickster',type:'tortoise',text:'At one sky feast, Tortoise called himself “All of You” and claimed everyone’s meal. Clever words. Terrible manners. The river shrine opens for people who share.'},{x:2200,y:1050,name:'Sky Cartographer',type:'human',text:'The last shrine wants judgement, not force. After all three echoes return, the eastern sky gate will open a storm trial. Keep moving. You can always try again.'},{x:2760,y:450,name:'Cloud Gardener',type:'human',text:'This realm is imaginary, but the stories that inspired it belong to living communities. Ask someone which tortoise story they grew up hearing.'}];
export const BUILDINGS=[{x:150,y:550,w:170,h:140,c:'#bc7455'},{x:410,y:520,w:160,h:130,c:'#9e624e'},{x:170,y:1160,w:150,h:140,c:'#aa7152'},{x:650,y:1230,w:150,h:130,c:'#976251'},{x:1180,y:500,w:140,h:120,c:'#7f8972'},{x:1450,y:400,w:160,h:140,c:'#8e8c78'},{x:1740,y:620,w:130,h:120,c:'#8d8b76'},{x:2250,y:350,w:140,h:100,c:'#a29caa'},{x:2750,y:1320,w:150,h:120,c:'#a196ac'}];
export function initialState(){return{version:1,relics:[],collected:[],coins:0,skin:'#5ddbcc',upgrade:false,won:false,seconds:0,visited:[],x:260,y:940};}
export function sanitiseState(o){const n=initialState();if(!o||o.version!==1)return n;n.relics=[...new Set((Array.isArray(o.relics)?o.relics:[]).filter(x=>SHRINES.some(s=>s.id===x)))];n.collected=[...new Set((Array.isArray(o.collected)?o.collected:[]).filter(x=>Number.isInteger(x)&&x>=0&&x<45))];n.coins=Math.max(0,Math.min(999,Number(o.coins)||0));n.skin=/^#[0-9a-f]{6}$/i.test(o.skin||'')?o.skin:n.skin;n.upgrade=!!o.upgrade;n.won=!!o.won&&n.relics.length===3;n.seconds=Math.max(0,Number(o.seconds)||0);n.visited=Array.isArray(o.visited)?o.visited.filter(x=>typeof x==='string').slice(0,10):[];n.x=Math.max(60,Math.min(3040,Number(o.x)||260));n.y=Math.max(60,Math.min(1640,Number(o.y)||940));return n;}
export function region(x){return x<1030?0:x<2050?1:2;}
export function blocked(x,y,s){if(x<42||y<90||x>WIDTH-42||y>HEIGHT-45)return true;for(const b of BUILDINGS)if(x>b.x-13&&x<b.x+b.w+13&&y>b.y-10&&y<b.y+b.h+10)return true;for(const [gx,need] of [[1030,'memory'],[2050,'balance']])if(Math.abs(x-gx)<64){if(y<850||y>1010)return true;if(!s.relics.includes(need))return true;}return false;}
export function move(p,dx,dy,s){if(!blocked(p.x+dx,p.y,s))p.x+=dx;if(!blocked(p.x,p.y+dy,s))p.y+=dy;}
export function grantRelic(s,id){if(!SHRINES.some(r=>r.id===id)||s.relics.includes(id))return false;s.relics.push(id);s.coins+=15;return true;}
export function balanced(values){return values.length===3&&values.every(x=>x===4);}
export function memoryCorrect(input,sequence){return input.length===sequence.length&&input.every((x,i)=>x===sequence[i]);}
export function purchaseUpgrade(s){if(s.upgrade||s.coins<20)return false;s.coins-=20;s.upgrade=true;return true;}
export const SHARDS=Array.from({length:45},(_,i)=>{const z=Math.floor(i/15),k=i%15;return{id:i,x:130+z*1030+(k%5)*172,y:270+Math.floor(k/5)*440+(k%2)*60};}).filter(s=>!BUILDINGS.some(b=>s.x>b.x-20&&s.x<b.x+b.w+20&&s.y>b.y-20&&s.y<b.y+b.h+20));
